function Icon({ name, size = 18 }: { name: IconName; size?: number }) {
  const Component = iconMap[name] ?? CircleHelp;
  return <Component size={size} strokeWidth={1.8} aria-hidden="true" />;
}

function ConfidenceBadge({ kind }: { kind: Confidence }) {
  const config: Record<Confidence, { label: string; className: string }> = {
    verified: { label: 'Verified', className: 'bg-[#dfeee7] text-[#22634d]' },
    estimate: { label: 'Estimate', className: 'bg-[#fbedd1] text-[#98651a]' },
    'user input': { label: 'Your input', className: 'bg-[#e5eaf6] text-[#39547f]' },
    assumption: { label: 'Assumption', className: 'bg-[#f5e3df] text-[#985448]' },
    'demo data': { label: 'Demo data', className: 'bg-[#e6e2f0] text-[#665584]' },
  };
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.08em] ${config[kind].className}`}>
      <span className="h-1.5 w-1.5 rounded-full bg-current opacity-70" />
      {config[kind].label}
    </span>
  );
}

