function ManagementPage({ type }: { type: 'schemes' | 'documents' | 'duplicates' | 'sources' }) {
  const config: Record<'schemes' | 'documents' | 'duplicates' | 'sources', { title: string; text: string; icon: LucideIcon }> = {
    schemes: { title: 'Scheme management', text: 'Keep eligibility, amount, and verification notes current.', icon: Landmark },
    documents: { title: 'Document & RAG management', text: 'Manage the public documents that ground advisor answers.', icon: FileText },
    duplicates: { title: 'Duplicate review', text: 'Resolve records before they create conflicting advice.', icon: Network },
    sources: { title: 'Data sources & assumptions', text: 'See where every signal comes from and what still needs a human check.', icon: BookOpen },
  };
  const copy = config[type];
  const ManagementIcon = copy.icon;
  const rows = type === 'schemes' ? [['PM MUDRA — Shishu', 'Ministry of Finance', '17 Jun 2025', 'Published'], ['Rashtriya Gokul Mission', 'Animal Husbandry', '10 Jun 2025', 'Published'], ['Dairy Entrepreneurship Development', 'NABARD', '28 May 2025', 'Needs review']] : type === 'documents' ? [['PM MUDRA guidelines 2025', 'PDF · 24 pages', 'Indexed', '12 chunks'], ['MP dairy unit costs', 'PDF · 11 pages', 'Indexed', '8 chunks'], ['Sehore household sample', 'CSV · 128 rows', 'Needs review', '—']] : type === 'duplicates' ? [['MUDRA Shishu', 'record-104 · record-118', '92% match', 'Review'], ['Dairy unit cost', 'record-073 · record-089', '84% match', 'Review'], ['Gokul Mission', 'record-041 · record-043', '76% match', 'Review']] : [['PM MUDRA guidelines', 'Government PDF', 'Verified', '17 Jun 2025'], ['Demo Village survey', 'Partner upload', 'Estimate', '12 Jun 2025'], ['Private dairy price', 'Field note', 'Assumption', 'Needs check']]; 
  return <div><PageIntro eyebrow="Admin workspace" title={copy.title} text={copy.text} action={<button type="button" className="gv-button inline-flex items-center gap-2 rounded-xl bg-[#1f5140] px-4 py-3 text-sm font-bold text-white" data-testid={`button-add-${type}`}><Plus size={16} /> {type === 'sources' ? 'Add source note' : 'Add record'}</button>} /><div className="gv-card overflow-x-auto rounded-2xl p-5"><div className="flex min-w-[680px] items-center justify-between"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e7efe4] text-[#397256]"><ManagementIcon size={19} /></span><div><p className="text-sm font-bold text-[#3d5b4a]">{rows.length} records in view</p><p className="text-xs text-[#89968c]">Local mock registry · changes are not published</p></div></div><div className="flex gap-2"><button type="button" className="rounded-lg border border-[#d9e0d5] p-2 text-[#687b6e]" data-testid={`button-filter-${type}`}><Filter size={16} /></button><button type="button" className="rounded-lg border border-[#d9e0d5] p-2 text-[#687b6e]" data-testid={`button-search-${type}`}><Search size={16} /></button></div></div><table className="mt-6 w-full min-w-[680px] text-left text-sm"><thead className="border-b border-[#e1e5dc] text-[10px] uppercase tracking-[.12em] text-[#89968c]"><tr><th className="pb-3">Name / source</th><th className="pb-3">Owner / detail</th><th className="pb-3">Status</th><th className="pb-3">Updated</th><th className="pb-3" /></tr></thead><tbody className="divide-y divide-[#edf0e8]">{rows.map((row, index) => <tr key={row[0]}><td className="py-4 font-bold text-[#3d5d4a]">{row[0]}</td><td className="py-4 text-[#718075]">{row[1]}</td><td className="py-4"><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${row[2].includes('Review') || row[2].includes('check') ? 'bg-[#f8e9c9] text-[#ac7427]' : row[2] === 'Assumption' ? 'bg-[#f5e3df] text-[#985448]' : 'bg-[#e6f0e4] text-[#397256]'}`}>{row[2]}</span></td><td className="py-4 text-[#89968c]">{row[3]}</td><td className="py-4 text-right"><button type="button" className="rounded-lg p-2 text-[#809187] hover:bg-[#eef2ea]" data-testid={`button-manage-row-${type}-${index}`}><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div></div>;
}

function AppRouter({ lang, setLang }: { lang: Lang; setLang: (lang: Lang) => void }) {
  const [location, navigate] = useLocation();
  if (location === '/') return <Landing lang={lang} setLang={setLang} />;
  if (location === '/login') return <AuthPage mode="login" onDemo={() => navigate('/dashboard')} />;
  if (location === '/register') return <AuthPage mode="register" onDemo={() => navigate('/dashboard')} />;
  if (location === '/language') return <LanguagePage lang={lang} setLang={setLang} />;
  let content: ReactNode;
  if (location === '/dashboard') content = <Dashboard lang={lang} />;
  else if (location === '/intake') content = <Intake />;
  else if (location === '/location') content = <LocationPage />;
  else if (location === '/finance') content = <Finance />;
  else if (location === '/scheme') content = <SchemeDetails />;
  else if (location === '/market') content = <MarketPage />;
  else if (location === '/competitor') content = <CompetitorPage />;
  else if (location === '/risk') content = <RiskPage />;
  else if (location === '/scenarios') content = <Scenarios />;
  else if (location === '/what-if') content = <Scenarios whatIf />;
  else if (location === '/advisor') content = <Advisor />;
  else if (location === '/report') content = <Report />;
  else if (location === '/dpr') content = <Report dpr />;
  else if (location === '/monitoring') content = <Monitoring />;
  else if (location === '/alerts') content = <AlertsPage />;
  else if (location === '/partners') content = <Partners />;
  else if (location === '/admin') content = <AdminPage />;
  else if (location === '/schemes') content = <ManagementPage type="schemes" />;
  else if (location === '/documents') content = <ManagementPage type="documents" />;
  else if (location === '/duplicates') content = <ManagementPage type="duplicates" />;
  else if (location === '/sources') content = <ManagementPage type="sources" />;
  else return <NotFound />;
  return <AppShell lang={lang}>{content}</AppShell>;
}

function App() {
  const [lang, setLang] = useState<Lang>('en');
  const isMock = useMemo(() => mockConfig.useMocks, []);
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={isMock ? lang : 'api'}><AppRouter lang={lang} setLang={setLang} /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;